def jump(nums):
    steps = end = farthest = 0
    for i in range(len(nums) - 1):
        farthest = max(farthest, i + nums[i])
        if farthest >= len(nums) - 1:
            return steps + 1
        if i == end:
            steps += 1
            end = farthest
    return steps

