#include <bits/stdc++.h>
using namespace std;

int jump(vector<int>& nums) {
    int steps = 0, end = 0, farthest = 0;
    for (int i = 0; i < (int)nums.size() - 1; ++i) {
        farthest = max(farthest, i + nums[i]);
        if (farthest >= (int)nums.size() - 1) return steps + 1;
        if (i == end) {
            ++steps;
            end = farthest;
        }
    }
    return steps;
}

